const rawOutput = $('RD-6 Trigger').first().json.stdout;
const lastRun = new Date($('Get last_run').first().json.last_run);

// Línea: 2026-07-13T03:10:57-03:00 Ubuntu sudo   ubuntu : TTY=... COMMAND=...
const lineRegex = /^(\S+)\s+\S+\s+sudo\s+(.*)$/;
const userCmdRegex = /^\s*(\S+)\s*:.*COMMAND=(.+)$/;

const categories = [
  { name: 'modificacion_etc', regex: /\/etc\// },
  { name: 'cuenta_usuario', regex: /\b(useradd|userdel|usermod|passwd)\b/i },
  { name: 'shell_interprete', regex: /\/bin\/(ba)?sh\b|\/usr\/bin\/(python|perl)\b/i }
];

function toArgentinaLocal(date) {
  return date.toLocaleString('es-AR', {
    timeZone: 'America/Argentina/Buenos_Aires',
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hour12: false
  });
}

const grouped = {};

for (const line of rawOutput.split('\n')) {
  const m = line.match(lineRegex);
  if (!m) continue;
  const [, tsRaw, message] = m;

  const eventTime = new Date(tsRaw);
  if (isNaN(eventTime.getTime()) || eventTime <= lastRun) continue;

  const um = message.match(userCmdRegex);
  if (!um) continue; // descarta las líneas pam_unix (no tienen COMMAND=)
  const [, user, command] = um;

  const matchedCategory = categories.find(c => c.regex.test(command));
  if (!matchedCategory) continue; // sudo normal, no sensible (ej. "sudo apt update")

  if (!grouped[user]) {
    grouped[user] = { user, commands: [], categories: new Set(), first_seen: eventTime, last_seen: eventTime };
  }
  grouped[user].commands.push({ command: command.trim(), timestamp: eventTime.toISOString(), category: matchedCategory.name });
  grouped[user].categories.add(matchedCategory.name);
  if (eventTime < grouped[user].first_seen) grouped[user].first_seen = eventTime;
  if (eventTime > grouped[user].last_seen) grouped[user].last_seen = eventTime;
}

const events = Object.values(grouped).map(g => ({
  user: g.user,
  command_count: g.commands.length,
  categories: Array.from(g.categories).join(','),
  commands_evidence: JSON.stringify(g.commands),
  first_seen: g.first_seen.toISOString(),
  last_seen: g.last_seen.toISOString(),
  first_seen_local: toArgentinaLocal(g.first_seen),
  last_seen_local: toArgentinaLocal(g.last_seen)
}));

return [{ json: { events } }];

